export const guideIds = new Set(guides.map((item) => `${item.section}/${item.slug}`));

export function getGuide(section: string, slug: string) {
  return guides.find((item) => item.section === section && item.slug === slug);
}

export function getGuideUrl(page: Pick<GuidePage, 'section' | 'slug'>) {
  return `/${page.section}/${page.slug}/`;
}

export function getGuideSectionUrl(section: GuideSection) {
  return `/${section}/`;
}

export function getRelatedGuides(ids: string[]) {
  return ids.map((id) => guides.find((item) => `${item.section}/${item.slug}` === id)).filter(Boolean) as GuidePage[];
}

export function getGuidesBySection(section: GuideSection) {
  return guides.filter((item) => item.section === section);
}
